import React from 'react';
import {AbsoluteFill, Easing, interpolate, useS, en, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;

// Sincronización con el guion
const TEMBLABAN = en('temblaban');
const ABRAZO = en('abrazó');
const VENGANZA = en('venganza');
const SALVAR = en('salvar');
const PRISIONES = en('prisiones');
const PROPOSITO = en('propósito');
const ROMPIERON = en('rompieron');
const DESIERTOS = en('desiertos');
const TRANSFORMARA = en('transformará');
const PREPARACION = en('preparación');
const AMEN = en('amén');

const C_ARENA = '#e6c9a2';
const C_EGIPTO = '#c5a368';
const C_ORO = '#ffd700';
const C_NOCHE = '#1a1a2e';
const C_CIELO = '#87ceeb';

const FiguraEstilo: React.FC<{
  x: number;
  y: number;
  escala: number;
  color: string;
  egipcio?: boolean;
  temblando?: number;
  brazos?: 'abajo' | 'abrazo' | 'ruego';
}> = ({x, y, escala, color, egipcio, temblando = 0, brazos = 'abajo'}) => {
  const dx = temblando * Math.sin(useS().s * 50) * 5;
  const u = escala;
  return (
    <div style={{position: 'absolute', left: x + dx, top: y, transform: 'translate(-50%, -100%)'}}>
      {/* Cabeza */}
      <div style={{position: 'absolute', left: -25 * u, top: -180 * u, width: 50 * u, height: 50 * u, borderRadius: '50%', background: color}} />
      {/* Tocado Egipcio */}
      {egipcio && (
        <div style={{position: 'absolute', left: -35 * u, top: -190 * u, width: 70 * u, height: 40 * u, background: '#333', borderRadius: '20px 20px 0 0', borderBottom: `4px solid ${C_ORO}`}} />
      )}
      {/* Cuerpo */}
      <div style={{position: 'absolute', left: -40 * u, top: -135 * u, width: 80 * u, height: 135 * u, background: color, borderRadius: '30px 30px 5px 5px'}} />
      {/* Brazos */}
      {brazos === 'abrazo' && (
        <>
          <div style={{position: 'absolute', left: -70 * u, top: -120 * u, width: 60 * u, height: 15 * u, background: color, borderRadius: 10, transform: 'rotate(20deg)'}} />
          <div style={{position: 'absolute', left: 10 * u, top: -120 * u, width: 60 * u, height: 15 * u, background: color, borderRadius: 10, transform: 'rotate(-20deg)'}} />
        </>
      )}
      {brazos === 'ruego' && (
        <>
          <div style={{position: 'absolute', left: -60 * u, top: -140 * u, width: 50 * u, height: 15 * u, background: color, borderRadius: 10, transform: 'rotate(-40deg)'}} />
          <div style={{position: 'absolute', left: 10 * u, top: -140 * u, width: 50 * u, height: 15 * u, background: color, borderRadius: 10, transform: 'rotate(40deg)'}} />
        </>
      )}
    </div>
  );
};

const Trigo: React.FC<{x: number; y: number; s: number; crecer: number}> = ({x, y, s, crecer}) => (
  <div style={{position: 'absolute', left: x, top: y, transform: `scale(${crecer})`, opacity: crecer}}>
    <div style={{position: 'absolute', bottom: 0, width: 4, height: 120, background: '#8b5a2b', transformOrigin: 'bottom', transform: `rotate(${Math.sin(s + x) * 5}deg)`}}>
      {[0, 1, 2, 3, 4].map(i => (
        <div key={i} style={{position: 'absolute', top: i * 15, left: i % 2 ? 4 : -12, width: 12, height: 20, background: C_ORO, borderRadius: '50% 50% 0 0', transform: `rotate(${i % 2 ? 45 : -45}deg)`}} />
      ))}
    </div>
  </div>
);

const Pilar: React.FC<{x: number; h: number; luz: number}> = ({x, h, luz}) => (
  <div style={{position: 'absolute', left: x, bottom: 0, width: 120, height: h, background: `linear-gradient(90deg, #2a2218, ${C_EGIPTO})`, borderTop: `10px solid ${C_ORO}`, opacity: luz}}>
    <div style={{position: 'absolute', top: 40, left: 0, right: 0, height: 20, background: 'rgba(0,0,0,0.2)'}} />
  </div>
);

export const Escena: React.FC = () => {
  const {s} = useS();

  // Estados de animación
  const enPalacio = interpolate(s, [0, PRISIONES], [1, 0], clamp);
  const temblorHermanos = interpolate(s, [TEMBLABAN, ABRAZO], [1, 0], clamp);
  const abrazoJose = interpolate(s, [ABRAZO, VENGANZA], [0, 1], clamp);
  const prisionVisible = interpolate(s, [PRISIONES - 0.5, PRISIONES + 0.5, PROPOSITO, PROPOSITO + 1], [0, 1, 1, 0], clamp);
  const trigoCreciendo = interpolate(s, [SALVAR, SALVAR + 3], [0, 1], clamp);
  const desiertoVisible = interpolate(s, [DESIERTOS - 0.5, TRANSFORMARA], [0, 1], clamp);
  const luzFinal = interpolate(s, [TRANSFORMARA, DUR], [0, 1], clamp);

  const zoom = interpolate(s, [0, DUR], [1, 1.15]);

  return (
    <AbsoluteFill style={{backgroundColor: '#0a0a0a', overflow: 'hidden'}}>
      {/* Fondo Cielo Dinámico */}
      <AbsoluteFill style={{
        background: `linear-gradient(180deg, ${interpolate(s, [PRISIONES, DESIERTOS], [C_CIELO, C_NOCHE], clamp)} 0%, #fff 100%)`,
        opacity: 0.3
      }} />

      <div style={{position: 'absolute', inset: 0, transform: `scale(${zoom})`, transformOrigin: 'center center'}}>

        {/* ESCENA 1: PALACIO / HERMANOS */}
        {enPalacio > 0 && (
          <AbsoluteFill style={{opacity: enPalacio}}>
            <Pilar x={100} h={1500} luz={enPalacio} />
            <Pilar x={860} h={1500} luz={enPalacio} />

            {/* Hermanos */}
            <FiguraEstilo x={350} y={1600} escala={0.8} color="#4a3b28" temblando={temblorHermanos} brazos={temblorHermanos > 0 ? 'ruego' : 'abajo'} />
            <FiguraEstilo x={450} y={1620} escala={0.75} color="#5a4b38" temblando={temblorHermanos} brazos={temblorHermanos > 0 ? 'ruego' : 'abajo'} />

            {/* José */}
            <FiguraEstilo 
              x={650} y={1600} escala={0.9} color="#1a1a1a" egipcio 
              brazos={abrazoJose > 0.5 ? 'abrazo' : 'abajo'} 
            />
          </AbsoluteFill>
        )}

        {/* ESCENA 2: PRISIÓN Y TRIGO */}
        {prisionVisible > 0 && (
          <AbsoluteFill style={{opacity: prisionVisible, background: 'rgba(0,0,0,0.6)'}}>
            {/* Rejas */}
            {Array.from({length: 8}).map((_, i) => (
              <div key={i} style={{position: 'absolute', left: 100 + i * 120, top: 0, bottom: 0, width: 15, background: '#333', boxShadow: '0 0 20px rgba(0,0,0,0.5)'}} />
            ))}
            <FiguraEstilo x={540} y={1400} escala={0.8} color="#222" brazos="ruego" />
          </AbsoluteFill>
        )}

        {/* TRIGO (Símbolo de Salvación) */}
        {trigoCreciendo > 0 && (
          <AbsoluteFill>
            {Array.from({length: 12}).map((_, i) => (
              <Trigo key={i} x={100 + (i * 80)} y={1700 - (i % 3 * 20)} s={s} crecer={trigoCreciendo} />
            ))}
          </AbsoluteFill>
        )}

        {/* ESCENA 3: DESIERTO A CAMINO DE LUZ */}
        {desiertoVisible > 0 && (
          <AbsoluteFill style={{opacity: desiertoVisible}}>
            {/* Dunas */}
            <svg width={W} height={600} style={{position: 'absolute', bottom: 0}}>
              <path d="M0 600 Q 300 400 600 550 T 1080 500 L 1080 600 L 0 600 Z" fill={C_ARENA} />
              <path d="M-100 600 Q 400 300 800 500 T 1200 450 L 1200 600 L -100 600 Z" fill={C_EGIPTO} opacity={0.6} />
            </svg>

            {/* Camino de Luz */}
            <div style={{
              position: 'absolute', left: 540, bottom: 0, width: 400, height: 1000,
              background: 'linear-gradient(0deg, rgba(255,215,0,0.4), transparent)',
              transform: 'translateX(-50%) perspective(500px) rotateX(60deg)',
              opacity: luzFinal
            }} />

            <FiguraEstilo x={540} y={1550} escala={0.8} color="#111" brazos={luzFinal > 0.5 ? 'abrazo' : 'abajo'} />
          </AbsoluteFill>
        )}

        {/* PARTÍCULAS DE BENDICIÓN */}
        {luzFinal > 0.1 && Array.from({length: 30}).map((_, i) => {
          const t = s + i;
          return (
            <div key={i} style={{
              position: 'absolute',
              left: (i * 137) % W,
              top: H - ((i * 251 + s * 100) % H),
              width: 6, height: 6, borderRadius: '50%',
              background: C_ORO,
              opacity: luzFinal * 0.6,
              boxShadow: `0 0 10px ${C_ORO}`
            }} />
          );
        })}
      </div>

      {/* Viñeta de paz */}
      <AbsoluteFill style={{
        background: 'radial-gradient(circle at 50% 40%, transparent 30%, rgba(0,0,0,0.4) 100%)',
        pointerEvents: 'none'
      }} />

      {/* Brillo Final Amén */}
      <AbsoluteFill style={{
        background: '#fff',
        opacity: interpolate(s, [AMEN, AMEN + 0.5, DUR], [0, 0.1, 0], clamp),
        pointerEvents: 'none'
      }} />
    </AbsoluteFill>
  );
};
